#include "../firmware/shared/DisplayState.h"
#include "../firmware/shared/Utc.h"
#include <cassert>
#include <iostream>
int main(){using namespace plantcare;const int64_t now=parseUtc("2026-11-12T15:00:00.000Z");assert(now>0);assert(parseUtc("2026-02-29T15:00:00.000Z")==-1);assert(parseUtc("2024-02-29T15:00:00.000Z")>0);assert(parseUtc("2026-11-12T25:00:00.000Z")==-1);assert(parseUtc("2026-11-12T15:00:00Z")==-1);DisplayState d;assert(d.stale(now,0,true));assert(!d.accept("b",1,"live","happy","happy",now,10,now,0,false));assert(d.accept("b",1,"live","happy","happy",now,10,now,0,true));assert(!d.stale(now+10000,10000,true));assert(d.stale(now+10001,10001,true));assert(d.stale(now,10001,true));assert(!d.accept("b",1,"live","happy","happy",now,10,now,0,true));assert(!d.accept("b",2,"live","happy","happy",now+6000,10,now,0,true));assert(!d.accept("b",2,"live","happy","evil",now,10,now,0,true));assert(!d.accept("b",2,"live","fake","happy",now,10,now,0,true));assert(!d.accept("b",2,"live","happy","happy",now,0,now,0,true));assert(!d.accept("new",1,"live","happy","happy",now-1,10,now,0,true));assert(d.accept("new",1,"simulated","watering_fault","sad",now+1,10,now+1,1,true));std::cout<<"Display watchdog and UTC assertion suite passed\n";}
